# Record-to-Record Comparator - runnable demo (JAH-ATK181-000001)
import difflib
RANK = 1
SIG = False
A, B = ({'title': 'Old Library', 'date': '1911', 'books': 1000}, {'title': 'Old Library', 'date': '1911', 'books': 2500, 'city': 'Springfield'})
WEIGHTS = {"title": 3.0, "date": 2.0}
changes, score, total = [], 0.0, 0.0
for field in sorted(set(A) | set(B)):
    w = WEIGHTS.get(field, 1.0); total += w
    if field not in A: changes.append((field, "ADDED", None, B[field]))
    elif field not in B: changes.append((field, "REMOVED", A[field], None))
    elif A[field] != B[field]:
        changes.append((field, "MODIFIED", A[field], B[field]))
    else: score += w
for field, kind, old, new in changes:
    print("[%s] %s: %r -> %r" % (kind, field, old, new))
    if RANK >= 2 and kind == "MODIFIED" and isinstance(old, str):
        sm = difflib.SequenceMatcher(None, str(old), str(new)).ratio()
        print("    text similarity: %.2f" % sm)
print("similarity score: %.2f" % (score/total if total else 1.0))
if SIG:
    print("Signature lineage stamp: JAH-SIG-CMP-" + "JAH-ATK181-000001")
print("record:", "JAH-ATK181-000001", "OK")

